import { type SemVer, type VersionLabel } from './version-scheme.js';
export declare const SELECTOR_MECHANISM_VERSION: "uia-ref-selector@1";
export type SelectorOperator = '=' | '>' | '>=' | '<' | '<=' | '^' | '~';
