```ts
export function validateDescriptor(descriptor, registry): StructuralResult {
  const links = descriptor.lineage;
  const counts = { CONTINUATION:0, FORKED_FROM:0, MERGED_FROM:0 };
  for (const link of links) {
    if (link.parent_version_id === descriptor.id) return { status:'REJECTED', code:'ERR_INVALID_RELATION', parent_version_id: link.parent_version_id };
    counts[link.relation] += 1;
  }
  // cardinality
  if (counts.CONTINUATION !== 0 && counts.CONTINUATION !== 1) return { status:'REJECTED', code:'ERR_INVALID_CARDINALITY' };
  ...
  if (counts.MERGED_FROM !== 0 && counts.MERGED_FROM < 2) ...
  // continuation participant
  const continuation = links.find(l => l.relation === 'CONTINUATION');
  if (continuation) {
    const parent = registry.versions().find(v => v.id === continuation.parent_version_id);
    if (parent && parent.participant_id !== descriptor.participant_id) {
      return { status:'REJECTED', code:'ERR_INVALID_RELATION', parent_version_id: continuation.parent_version_id };
    }
  }
  return { status:'VALID' };
}
```
