```ts
import type { IdentityVersionDescriptor, ParticipantRecord } from './entities.js';
import type { DeepReadonly } from './ownership.js';
import type { IdentityVersionID } from './primitives.js';

export interface Registry {
  participants(): readonly DeepReadonly<ParticipantRecord>[];
  versions(): readonly DeepReadonly<IdentityVersionDescriptor>[];
}

export type StructuralResult =
  | { readonly status: 'VALID' }
  | { readonly status: 'INVALID' }
  | {
      readonly status: 'REJECTED';
      readonly code: 'ERR_INVALID_RELATION' | 'ERR_INVALID_CARDINALITY';
      readonly parent_version_id?: IdentityVersionID;
    };

const CARDINALITY: Readonly<Record<LineageRelationType, { readonly min: number; readonly max: number }>> = {
  CONTINUATION: { min: 1, max: 1 },
  FORKED_FROM: { min: 1, max: 1 },
  MERGED_FROM: { min: 2, max: Number.POSITIVE_INFINITY },
};
```
Need import LineageRelationType and LineageLink? Only type.

`validateDescriptor`:
```ts
export function validateDescriptor(
  descriptor: DeepReadonly<IdentityVersionDescriptor>,
  registry: Registry,
): StructuralResult {
  for (const link of descriptor.lineage) {
    if (link.parent_version_id === descriptor.id) {
      return { status: 'REJECTED', code: 'ERR_INVALID_RELATION', parent_version_id: link.parent_version_id };
    }
  }

  const counts: Record<LineageRelationType, number> = { CONTINUATION: 0, FORKED_FROM: 0, MERGED_FROM: 0 };
  for (const link of descriptor.lineage) counts[link.relation] += 1;

  for (const relation of Object.keys(CARDINALITY) as LineageRelationType[]) {
    const count = counts[relation];
    if (count === 0) continue;
    const rule = CARDINALITY[relation];
    if (count < rule.min || count > rule.max) {
      return { status: 'REJECTED', code: 'ERR_INVALID_CARDINALITY' };
    }
  }

  const continuation = descriptor.lineage.find((l) => l.relation === 'CONTINUATION');
  if (continuation !== undefined) {
    const parent = findVersion(registry, continuation.parent_version_id);
    if (parent !== undefined && parent.participant_id !== descriptor.participant_id) {
      return { status: 'REJECTED', code: 'ERR_INVALID_RELATION', parent_version_id: continuation.parent_version_id };
    }
  }

  return { status: 'VALID' };
}

function findVersion(registry, id): DeepReadonly<IdentityVersionDescriptor> | undefined {
  return registry.versions().find((version) => version.id === id);
}
```
Note: `count > rule.max` with Infinity fine.

`INVALID` variant unused; keep per plan. Maybe add comment "reserved".

Registry participants unused in validation; fine. Could use `registry.participants()` to check descriptor's participant exists? Not required; don't.

Hmm: should CONTINUATION check all continuation links or just one? Cardinality ensures exactly 1, so find returns it.

Edge: cardinality check order before participant: if two CONTINUATION with cross-participant → cardinality wins. Fine.

Determinism: counts by relation; self-parent first. Fine.

Export via barrel:
```ts
export * from './lineage.js';
```
Or explicit. Use explicit to control:
```ts
export { validateDescriptor } from './lineage.js';
export type { Registry, StructuralResult } from './lineage.js';
```

Also entity constructors exported via `export * from './entities.js'` already.

Sonar/lint considerations:
- `Object.keys(CARDINALITY) as LineageRelationType[]` cast.
- `Number.POSITIVE_INFINITY`.

Implement now. Use edits.

