Kosaraju:
```ts
function findCyclicComponents(nodes, edges): readonly (readonly IdentityVersionID[])[] {
  const adjacency = buildAdjacency(nodes, edges);
  const order: IdentityVersionID[] = [];
  const visited = new Set<IdentityVersionID>();
  for (const start of nodes) { // nodes sorted
    if (visited.has(start)) continue;
    // iterative DFS with stack of [node, index]
    const stack: Array<{node: IdentityVersionID; next: number}> = [{node:start, next:0}];
    visited.add(start);
    while (stack.length > 0) {
      const frame = stack[stack.length-1];
      const neighbors = adjacency.get(frame.node) ?? [];
      if (frame.next < neighbors.length) {
        const neighbor = neighbors[frame.next];
        frame.next += 1;
        if (!visited.has(neighbor) && adjacency.has(neighbor)) {
          visited.add(neighbor);
          stack.push({node: neighbor, next: 0});
        }
      } else {
        order.push(frame.node);
        stack.pop();
      }
    }
  }
  // reverse graph
  const reverse = new Map<IdentityVersionID, IdentityVersionID[]>();
  for (const id of nodes) reverse.set(id, []);
  for (const [child, parents] of adjacency) {
    for (const parent of parents) {
      if (reverse.has(parent)) reverse.get(parent)!.push(child);
    }
  }
  for (const list of reverse.values()) list.sort(compareIds);

  const components: IdentityVersionID[][] = [];
  const assigned = new Set<IdentityVersionID>();
  for (let i = order.length - 1; i >= 0; i -= 1) {
    const start = order[i];
    if (assigned.has(start)) continue;
    const component: IdentityVersionID[] = [];
    const stack = [start];
    assigned.add(start);
    while (stack.length > 0) {
      const node = stack.pop()!;
      component.push(node);
      for (const child of reverse.get(node) ?? []) {
        if (!assigned.has(child)) { assigned.add(child); stack.push(child); }
      }
    }
    component.sort(compareIds);
    if (isCyclicComponent(component, adjacency)) components.push(component);
  }
  components.sort((a,b) => compareIds(a[0], b[0])); // each nonempty
  return components;
}

function isCyclicComponent(component, adjacency): boolean {
  if (component.length > 1) return true;
  const only = component[0];
  return (adjacency.get(only) ?? []).includes(only);
}
```
Self-loop: component size 1, adjacency includes itself → cyclic.

